import type { MaybeRefOrGetter } from 'vue';

export const OG_IMAGE_WIDTH = 1200;
export const OG_IMAGE_HEIGHT = 630;

/**
 * Sets the Open Graph and Twitter image tags for a page.
 *
 * `name` is a file in `public/og/` (without `.jpg`), generated by
 * `npm run build:og`. URLs are absolute because Facebook, LinkedIn,
 * WhatsApp and Slack ignore relative og:image URLs.
 */
export function useOgImage(name: string, alt: MaybeRefOrGetter<string>) {
  const url = useRequestURL();
  const image = `${url.origin}/og/${name}.jpg`;

  useSeoMeta({
    ogUrl: `${url.origin}${url.pathname}`,
    ogImage: image,
    ogImageWidth: OG_IMAGE_WIDTH,
    ogImageHeight: OG_IMAGE_HEIGHT,
    ogImageType: 'image/jpeg',
    ogImageAlt: alt,
    twitterCard: 'summary_large_image',
    twitterImage: image,
    twitterImageAlt: alt,
  });
}
